import java.util.stream.IntStream;

public class binarytrees {
    private static final int MIN_DEPTH = 4;

    public static void main(String[] args) {
        int n = Integer.parseInt(args[0]);

        int maxDepth = Math.max(MIN_DEPTH + 2, n);
        int stretchDepth = maxDepth + 1;

        StringBuilder out = new StringBuilder();

        TreeNode stretchTree = bottomUpTree(stretchDepth);
        out.append("stretch tree of depth ")
           .append(stretchDepth)
           .append("\t check: ")
           .append(stretchTree.itemCheck())
           .append('\n');

        TreeNode longLivedTree = bottomUpTree(maxDepth);

        int resultCount = ((maxDepth - MIN_DEPTH) / 2) + 1;
        String[] results = new String[resultCount];

        IntStream.range(0, resultCount).parallel().forEach(i -> {
            int depth = MIN_DEPTH + (i << 1);
            int iterations = 1 << (maxDepth - depth + MIN_DEPTH);
            int check = 0;

            for (int j = 0; j < iterations; j++) {
                check += bottomUpTree(depth).itemCheck();
            }

            results[i] = iterations + "\t trees of depth " + depth + "\t check: " + check;
        });

        for (String result : results) {
            out.append(result).append('\n');
        }

        out.append("long lived tree of depth ")
           .append(maxDepth)
           .append("\t check: ")
           .append(longLivedTree.itemCheck())
           .append('\n');

        System.out.print(out.toString());
    }

    private static TreeNode bottomUpTree(int depth) {
        if (depth == 0) {
            return new TreeNode(null, null);
        }
        return new TreeNode(bottomUpTree(depth - 1), bottomUpTree(depth - 1));
    }

    private static final class TreeNode {
        private final TreeNode left;
        private final TreeNode right;

        private TreeNode(TreeNode left, TreeNode right) {
            this.left = left;
            this.right = right;
        }

        private int itemCheck() {
            if (left == null) {
                return 1;
            }
            return 1 + left.itemCheck() + right.itemCheck();
        }
    }
}
