import java.util.concurrent.atomic.AtomicInteger;

public class fannkuchredux {
    private static int n;
    private static int[] fact;
    private static int totalPermutations;
    private static int chunkSize;
    private static int taskCount;

    private static int[] taskChecksums;
    private static int[] taskMaxFlips;
    private static final AtomicInteger nextTask = new AtomicInteger();

    public static void main(String[] args) throws Exception {
        n = Integer.parseInt(args[0]);

        fact = new int[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i;
        }

        totalPermutations = fact[n];

        int threads = Runtime.getRuntime().availableProcessors();
        if (threads < 1) threads = 1;

        int wantedChunks = threads * 24;
        if (wantedChunks < 1) wantedChunks = 1;
        if (wantedChunks > totalPermutations) wantedChunks = totalPermutations;

        chunkSize = (totalPermutations + wantedChunks - 1) / wantedChunks;
        taskCount = (totalPermutations + chunkSize - 1) / chunkSize;

        taskChecksums = new int[taskCount];
        taskMaxFlips = new int[taskCount];

        int threadCount = Math.min(threads, taskCount);
        Thread[] workers = new Thread[threadCount];

        for (int i = 0; i < threadCount; i++) {
            workers[i] = new Thread(new Worker());
            workers[i].start();
        }

        for (int i = 0; i < threadCount; i++) {
            workers[i].join();
        }

        int checksum = 0;
        int maxFlips = 0;

        for (int i = 0; i < taskCount; i++) {
            checksum += taskChecksums[i];
            if (taskMaxFlips[i] > maxFlips) {
                maxFlips = taskMaxFlips[i];
            }
        }

        System.out.print(checksum);
        System.out.print('\n');
        System.out.print("Pfannkuchen(");
        System.out.print(n);
        System.out.print(") = ");
        System.out.print(maxFlips);
        System.out.print('\n');
    }

    private static final class Worker implements Runnable {
        public void run() {
            int task;
            while ((task = nextTask.getAndIncrement()) < taskCount) {
                computeTask(task);
            }
        }
    }

    private static void computeTask(int task) {
        int idxMin = task * chunkSize;
        int idxMax = idxMin + chunkSize;
        if (idxMax > totalPermutations) {
            idxMax = totalPermutations;
        }

        int[] perm = new int[n];
        int[] temp = new int[n];
        int[] count = new int[n];

        for (int i = 0; i < n; i++) {
            perm[i] = i;
        }

        int idx = idxMin;

        for (int i = n - 1; i > 0; i--) {
            int d = idx / fact[i];
            count[i] = d;
            idx %= fact[i];

            System.arraycopy(perm, 0, temp, 0, i + 1);
            int size = i + 1;
            for (int j = 0; j < size; j++) {
                perm[j] = temp[(j + d) % size];
            }
        }

        int checksum = 0;
        int maxFlips = 0;
        int sign = ((idxMin & 1) == 0) ? 1 : -1;
        idx = idxMin;

        while (true) {
            int first = perm[0];

            if (first != 0) {
                System.arraycopy(perm, 0, temp, 0, n);

                int flips = 0;
                int k = first;

                do {
                    int next = temp[k];
                    temp[k] = k;

                    int lo = 1;
                    int hi = k - 1;
                    while (lo < hi) {
                        int t = temp[lo];
                        temp[lo] = temp[hi];
                        temp[hi] = t;
                        lo++;
                        hi--;
                    }

                    k = next;
                    flips++;
                } while (k != 0);

                checksum += sign * flips;

                if (flips > maxFlips) {
                    maxFlips = flips;
                }
            }

            if (++idx == idxMax) {
                break;
            }

            sign = -sign;

            first = perm[0];
            perm[0] = perm[1];
            perm[1] = first;

            int i = 1;
            while (++count[i] > i) {
                count[i] = 0;
                i++;

                first = perm[0];
                for (int j = 0; j < i; j++) {
                    perm[j] = perm[j + 1];
                }
                perm[i] = first;
            }
        }

        taskChecksums[task] = checksum;
        taskMaxFlips[task] = maxFlips;
    }
}
