import java.nio.charset.StandardCharsets;

public class fasta {
    private static final int IM = 139968;
    private static final int IA = 3877;
    private static final int IC = 29573;

    private static int seed = 42;

    private static final byte[] ALU = (
            "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA" +
            "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT" +
            "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG" +
            "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG" +
            "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA"
    ).getBytes(StandardCharsets.US_ASCII);

    private static final byte[] HEADER_ONE =
            ">ONE Homo sapiens alu\n".getBytes(StandardCharsets.US_ASCII);
    private static final byte[] HEADER_TWO =
            ">TWO IUB ambiguity codes\n".getBytes(StandardCharsets.US_ASCII);
    private static final byte[] HEADER_THREE =
            ">THREE Homo sapiens frequency\n".getBytes(StandardCharsets.US_ASCII);

    public static void main(String[] args) throws Exception {
        int n = Integer.parseInt(args[0]);

        OutputStream out = new BufferedOutputStream(System.out, 1 << 20);

        out.write(HEADER_ONE);
        repeatFasta(out, ALU, 2 * n);

        byte[] iubMap = makeLookup(
                new byte[]{'a', 'c', 'g', 't', 'B', 'D', 'H', 'K', 'M', 'N', 'R', 'S', 'V', 'W', 'Y'},
                new double[]{0.27, 0.12, 0.12, 0.27, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02}
        );

        out.write(HEADER_TWO);
        randomFasta(out, iubMap, 3 * n);

        byte[] homoMap = makeLookup(
                new byte[]{'a', 'c', 'g', 't'},
                new double[]{0.3029549426680, 0.1979883004921, 0.1975473066391, 0.3015094502008}
        );

        out.write(HEADER_THREE);
        randomFasta(out, homoMap, 5 * n);

        out.flush();
    }

    private static byte[] makeLookup(byte[] symbols, double[] probabilities) {
        double[] cumulative = new double[probabilities.length];
        double sum = 0.0;
        for (int i = 0; i < probabilities.length; i++) {
            sum += probabilities[i];
            cumulative[i] = sum;
        }

        byte[] lookup = new byte[IM];
        for (int s = 0; s < IM; s++) {
            double r = (double) s / IM;
            for (int i = 0; i < cumulative.length; i++) {
                if (cumulative[i] > r) {
                    lookup[s] = symbols[i];
                    break;
                }
            }
        }
        return lookup;
    }

    private static void repeatFasta(OutputStream out, byte[] sequence, int count) throws Exception {
        byte[] line = new byte[61];
        line[60] = '\n';

        int pos = 0;
        int remaining = count;
        int sequenceLength = sequence.length;

        while (remaining > 0) {
            int len = remaining < 60 ? remaining : 60;

            for (int i = 0; i < len; i++) {
                line[i] = sequence[pos++];
                if (pos == sequenceLength) {
                    pos = 0;
                }
            }

            line[len] = '\n';
            out.write(line, 0, len + 1);
            remaining -= len;
        }
    }

    private static void randomFasta(OutputStream out, byte[] lookup, int count) throws Exception {
        byte[] line = new byte[61];
        line[60] = '\n';

        int remaining = count;
        while (remaining > 0) {
            int len = remaining < 60 ? remaining : 60;

            for (int i = 0; i < len; i++) {
                seed = (seed * IA + IC) % IM;
                line[i] = lookup[seed];
            }

            line[len] = '\n';
            out.write(line, 0, len + 1);
            remaining -= len;
        }
    }
}
