import java.io.InputStream;
import java.io.IOException;

public class knucleotide {
    private static final String[] TARGETS = {
        "GGT",
        "GGTA",
        "GGTATT",
        "GGTATTTTAATT",
        "GGTATTTTAATTTATAGT"
    };

    private static final byte[] THREE_HEADER = { 'T', 'H', 'R', 'E', 'E' };
    private static final char[] ALPHABET = { 'A', 'C', 'G', 'T' };

    private static final long MASK3  = (1L << (2 * 3))  - 1L;
    private static final long MASK4  = (1L << (2 * 4))  - 1L;
    private static final long MASK6  = (1L << (2 * 6))  - 1L;
    private static final long MASK12 = (1L << (2 * 12)) - 1L;
    private static final long MASK18 = (1L << (2 * 18)) - 1L;
    private static final long MAX_MASK = MASK18;

    private static final long CODE_GGT                  = encodeTarget("GGT");
    private static final long CODE_GGTA                 = encodeTarget("GGTA");
    private static final long CODE_GGTATT               = encodeTarget("GGTATT");
    private static final long CODE_GGTATTTTAATT         = encodeTarget("GGTATTTTAATT");
    private static final long CODE_GGTATTTTAATTTATAGT   = encodeTarget("GGTATTTTAATTTATAGT");

    static final class Stats {
        long length;
        int previous;
        long rolling;

        final long[] count1 = new long[4];
        final long[] count2 = new long[16];
        final long[] targetCounts = new long[5];

        void addBase(int base) {
            count1[base]++;

            if (length != 0) {
                count2[(previous << 2) | base]++;
            }
            previous = base;

            rolling = ((rolling << 2) | base) & MAX_MASK;
            long n = ++length;

            if (n >= 3  && (rolling & MASK3)  == CODE_GGT)                targetCounts[0]++;
            if (n >= 4  && (rolling & MASK4)  == CODE_GGTA)               targetCounts[1]++;
            if (n >= 6  && (rolling & MASK6)  == CODE_GGTATT)             targetCounts[2]++;
            if (n >= 12 && (rolling & MASK12) == CODE_GGTATTTTAATT)       targetCounts[3]++;
            if (n >= 18 && (rolling & MASK18) == CODE_GGTATTTTAATTTATAGT) targetCounts[4]++;
        }
    }

    public static void main(String[] args) throws Exception {
        Integer.parseInt(args[0]);

        Stats allStats = new Stats();
        Stats threeStats = new Stats();

        boolean seenThree = false;
        boolean activeThree = false;

        boolean atLineStart = true;
        boolean inHeader = false;

        int headerPos = 0;
        boolean headerPossible = true;
        boolean headerIsThree = false;

        byte[] buffer = new byte[1 << 16];
        InputStream in = System.in;
        int read;

        while ((read = in.read(buffer)) != -1) {
            for (int i = 0; i < read; i++) {
                int b = buffer[i] & 0xff;

                if (inHeader) {
                    if (b == '\n' || b == '\r') {
                        inHeader = false;
                        activeThree = headerIsThree;
                        if (headerIsThree) {
                            seenThree = true;
                        }
                        atLineStart = true;
                    } else {
                        if (headerPos < 5) {
                            int u = toUpperAscii(b);
                            if (u != THREE_HEADER[headerPos]) {
                                headerPossible = false;
                            }
                            headerPos++;
                            if (headerPos == 5 && headerPossible) {
                                headerIsThree = true;
                            }
                        }
                        atLineStart = false;
                    }
                    continue;
                }

                if (atLineStart && b == '>') {
                    inHeader = true;
                    activeThree = false;
                    headerPos = 0;
                    headerPossible = true;
                    headerIsThree = false;
                    atLineStart = false;
                    continue;
                }

                if (b == '\n' || b == '\r') {
                    atLineStart = true;
                    continue;
                }

                atLineStart = false;

                int base = baseCode(b);
                if (base >= 0) {
                    if (!seenThree) {
                        allStats.addBase(base);
                    }
                    if (activeThree) {
                        threeStats.addBase(base);
                    }
                }
            }
        }

        if (inHeader && headerIsThree) {
            seenThree = true;
        }

        Stats stats = seenThree ? threeStats : allStats;

        StringBuilder out = new StringBuilder(4096);
        writeFrequencies(out, stats.count1, 1, stats.length);
        writeFrequencies(out, stats.count2, 2, stats.length);

        for (int i = 0; i < TARGETS.length; i++) {
            out.append(stats.targetCounts[i]).append('\t').append(TARGETS[i]).append('\n');
        }

        System.out.print(out.toString());
    }

    private static int toUpperAscii(int b) {
        return (b >= 'a' && b <= 'z') ? b - 32 : b;
    }

    private static int baseCode(int b) {
        switch (b) {
            case 'A': case 'a': return 0;
            case 'C': case 'c': return 1;
            case 'G': case 'g': return 2;
            case 'T': case 't': return 3;
            default: return -1;
        }
    }

    private static long encodeTarget(String s) {
        long code = 0;
        for (int i = 0; i < s.length(); i++) {
            code = (code << 2) | baseCode(s.charAt(i));
        }
        return code;
    }

    private static void writeFrequencies(StringBuilder out, long[] counts, int k, long sequenceLength) {
        long total = sequenceLength - k + 1;
        if (total <= 0) {
            out.append('\n');
            return;
        }

        int size = 1 << (2 * k);
        int[] codes = new int[size];
        int used = 0;

        for (int i = 0; i < size; i++) {
            if (counts[i] > 0) {
                codes[used++] = i;
            }
        }

        for (int i = 1; i < used; i++) {
            int key = codes[i];
            int j = i - 1;
            while (j >= 0 && comesBefore(key, codes[j], counts)) {
                codes[j + 1] = codes[j];
                j--;
            }
            codes[j + 1] = key;
        }

        for (int i = 0; i < used; i++) {
            int code = codes[i];
            appendKmer(out, code, k);
            out.append(' ');
            appendPercent(out, counts[code], total);
            out.append('\n');
        }
        out.append('\n');
    }

    private static boolean comesBefore(int a, int b, long[] counts) {
        long ca = counts[a];
        long cb = counts[b];
        if (ca != cb) {
            return ca > cb;
        }
        return a < b;
    }

    private static void appendKmer(StringBuilder out, int code, int k) {
        for (int shift = (k - 1) * 2; shift >= 0; shift -= 2) {
            out.append(ALPHABET[(code >> shift) & 3]);
        }
    }

    private static void appendPercent(StringBuilder out, long count, long total) {
        long scaled = (count * 100000L + total / 2) / total;
        out.append(scaled / 1000).append('.');

        long frac = scaled % 1000;
        if (frac < 100) out.append('0');
        if (frac < 10) out.append('0');
        out.append(frac);
    }
}
