import java.io.BufferedOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicInteger;

public class mandelbrot {
    private static final int MAX_ITER = 50;
    private static final double LIMIT_SQUARED = 4.0;

    private static int N;
    private static int ROW_BYTES;
    private static double[] CR;
    private static byte[] IMAGE;
    private static final AtomicInteger NEXT_ROW = new AtomicInteger();

    public static void main(String[] args) throws Exception {
        N = Integer.parseInt(args[0]);
        ROW_BYTES = (N + 7) >>> 3;
        CR = new double[N];
        IMAGE = new byte[N * ROW_BYTES];

        for (int x = 0; x < N; x++) {
            CR[x] = (2.0 * x / N) - 1.5;
        }

        int threadCount = Math.min(N, Runtime.getRuntime().availableProcessors());
        Thread[] threads = new Thread[threadCount];

        for (int i = 0; i < threadCount; i++) {
            threads[i] = new Thread(new Worker());
            threads[i].start();
        }

        for (Thread t : threads) {
            t.join();
        }

        BufferedOutputStream out = new BufferedOutputStream(System.out, 1 << 16);
        out.write(("P4\n" + N + " " + N + "\n").getBytes(StandardCharsets.US_ASCII));
        out.write(IMAGE);
        out.flush();
    }

    private static final class Worker implements Runnable {
        public void run() {
            int y;
            while ((y = NEXT_ROW.getAndIncrement()) < N) {
                computeRow(y);
            }
        }
    }

    private static void computeRow(int y) {
        final int n = N;
        final int rowBytes = ROW_BYTES;
        final double[] crValues = CR;
        final byte[] image = IMAGE;

        final double ci = (2.0 * y / n) - 1.0;
        final double ci2 = ci * ci;
        final int rowOffset = y * rowBytes;

        int x = 0;
        for (int byteIndex = 0; byteIndex < rowBytes; byteIndex++) {
            int byteAcc = 0;
            int bits = n - x;
            if (bits > 8) {
                bits = 8;
            }

            for (int bit = 0; bit < bits; bit++, x++) {
                final double cr = crValues[x];
                boolean inside;

                double crm = cr - 0.25;
                double q = crm * crm + ci2;

                if (q * (q + crm) < 0.25 * ci2) {
                    inside = true;
                } else {
                    double crp = cr + 1.0;
                    inside = crp * crp + ci2 < 0.0625;
                }

                if (!inside) {
                    double zr = 0.0;
                    double zi = 0.0;
                    double tr = 0.0;
                    double ti = 0.0;

                    int iter = MAX_ITER;
                    while (iter-- > 0 && tr + ti <= LIMIT_SQUARED) {
                        zi = 2.0 * zr * zi + ci;
                        zr = tr - ti + cr;
                        tr = zr * zr;
                        ti = zi * zi;
                    }

                    inside = tr + ti <= LIMIT_SQUARED;
                }

                byteAcc = (byteAcc << 1) | (inside ? 1 : 0);
            }

            byteAcc <<= 8 - bits;
            image[rowOffset + byteIndex] = (byte) byteAcc;
        }
    }
}
