public class pidigits {
    private static final class PiDigitSpigot {
        private static final BigInteger ZERO = BigInteger.ZERO;
        private static final BigInteger ONE = BigInteger.ONE;
        private static final BigInteger TWO = BigInteger.valueOf(2);
        private static final BigInteger THREE = BigInteger.valueOf(3);
        private static final BigInteger FOUR = BigInteger.valueOf(4);
        private static final BigInteger TEN = BigInteger.TEN;

        private BigInteger q = ONE;
        private BigInteger r = ZERO;
        private BigInteger t = ONE;

        private long k = 1;
        private long l = 3;
        private int n = 3;

        int nextDigit() {
            for (;;) {
                if (q.multiply(FOUR).add(r).subtract(t).compareTo(t.multiply(BigInteger.valueOf(n))) < 0) {
                    int digit = n;

                    BigInteger nr = r.subtract(t.multiply(BigInteger.valueOf(digit))).multiply(TEN);
                    BigInteger nn = q.multiply(THREE).add(r).multiply(TEN).divide(t)
                            .subtract(BigInteger.valueOf(10L * digit));

                    q = q.multiply(TEN);
                    r = nr;
                    n = nn.intValue();

                    return digit;
                } else {
                    BigInteger lBI = BigInteger.valueOf(l);
                    BigInteger kBI = BigInteger.valueOf(k);

                    BigInteger nr = q.multiply(TWO).add(r).multiply(lBI);
                    BigInteger tNew = t.multiply(lBI);

                    BigInteger nn = q.multiply(BigInteger.valueOf(7L * k + 2L))
                            .add(r.multiply(lBI))
                            .divide(tNew);

                    q = q.multiply(kBI);
                    r = nr;
                    t = tNew;
                    k++;
                    l += 2;
                    n = nn.intValue();
                }
            }
        }
    }

    public static void main(String[] args) {
        int n = Integer.parseInt(args[0]);

        PiDigitSpigot pi = new PiDigitSpigot();
        StringBuilder output = new StringBuilder(n + (n / 10 + 1) * 6);
        char[] line = new char[10];

        for (int i = 0; i < n; i++) {
            line[i % 10] = (char) ('0' + pi.nextDigit());

