                    i = j + 1;
                } else {
                    System.arraycopy(s, i, out, o, len - i);
                    o += len - i;
                    break;
                }
            } else {
                out[o++] = s[i++];
            }
        }

        return new Bytes(out, o);
    }

    private static byte[] grow(byte[] a, int needed) {
        int n = a.length + (a.length >> 1) + 16;
        if (n < needed) {
            n = needed;
        }
        return Arrays.copyOf(a, n);
    }
