            }
            if (pos >= length) {
                break;
            }

            while (pos < length && data[pos] != '\n') {
                pos++;
            }
            if (pos < length) {
                pos++;
            }

            int seqStart = pos;

            while (pos < length && data[pos] != '>') {
                pos++;
            }

            reverseComplement(data, seqStart, pos);
        }

        System.out.write(data, 0, length);
    }

    private static byte[] readAllStdin() throws IOException {
        InputStream in = System.in;
        byte[] buffer = new byte[1 << 20];
        int length = 0;

        while (true) {
            if (length == buffer.length) {
                buffer = Arrays.copyOf(buffer, buffer.length << 1);
            }

            int n = in.read(buffer, length, buffer.length - length);
            if (n < 0) {
                break;
            }
            if (n > 0) {
                length += n;
            }
        }

        return Arrays.copyOf(buffer, length);
    }

    private static void reverseComplement(byte[] data, int start, int end) {
        int left = start;
        int right = end - 1;

        while (left <= right) {
            while (left <= right && (data[left] == '\n' || data[left] == '\r')) {
                left++;
            }
            while (left <= right && (data[right] == '\n' || data[right] == '\r')) {
                right--;
            }
            if (left > right) {
                break;
            }

            byte a = data[left];
            byte b = data[right];

            data[left] = COMPLEMENT[b & 0xff];
            data[right] = COMPLEMENT[a & 0xff];

            left++;
            right--;
        }
    }

    private static byte[] makeComplementTable() {
        byte[] table = new byte[256];

        for (int i = 0; i < table.length; i++) {
            table[i] = (byte) i;
