import java.util.Arrays;
import java.util.Locale;
import java.util.concurrent.CyclicBarrier;

public class spectralnorm {
    private static final int ITERATIONS = 10;

    private static int n;
    private static double[] u;
    private static double[] v;
    private static double[] tmp;
    private static CyclicBarrier barrier;

    private static final class Worker extends Thread {
        private final int start;
        private final int end;

        Worker(int start, int end) {
            this.start = start;
            this.end = end;
        }

        @Override
        public void run() {
            try {
                for (int i = 0; i < ITERATIONS; i++) {
                    multiplyAv(u, tmp, start, end);
                    barrier.await();

                    multiplyAtv(tmp, v, start, end);
                    barrier.await();

                    multiplyAv(v, tmp, start, end);
                    barrier.await();

                    multiplyAtv(tmp, u, start, end);
                    barrier.await();
                }
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
    }

    private static void multiplyAv(double[] input, double[] output, int start, int end) {
        final int size = n;

        for (int i = start; i < end; i++) {
            double sum = 0.0;

            double denom = ((double) i * ((double) i + 1.0) * 0.5) + i + 1.0;
            double increment = i + 1.0;

            for (int j = 0; j < size; j++) {
                sum += input[j] / denom;
                denom += increment;
                increment += 1.0;
            }

            output[i] = sum;
        }
    }

    private static void multiplyAtv(double[] input, double[] output, int start, int end) {
        final int size = n;

        for (int i = start; i < end; i++) {
            double sum = 0.0;

            double denom = ((double) i * ((double) i + 1.0) * 0.5) + 1.0;
            double increment = i + 2.0;

            for (int j = 0; j < size; j++) {
                sum += input[j] / denom;
                denom += increment;
                increment += 1.0;
            }

            output[i] = sum;
        }
    }

    public static void main(String[] args) throws Exception {
        n = Integer.parseInt(args[0]);

        u = new double[n];
        v = new double[n];
        tmp = new double[n];

        Arrays.fill(u, 1.0);

        int threads = n < 200 ? 1 : Math.min(Runtime.getRuntime().availableProcessors(), n);

        if (threads <= 1) {
            for (int i = 0; i < ITERATIONS; i++) {
                multiplyAv(u, tmp, 0, n);
                multiplyAtv(tmp, v, 0, n);
                multiplyAv(v, tmp, 0, n);
                multiplyAtv(tmp, u, 0, n);
            }
        } else {
            barrier = new CyclicBarrier(threads);
            Worker[] workers = new Worker[threads];

            for (int i = 0; i < threads; i++) {
                int start = i * n / threads;
                int end = (i + 1) * n / threads;
                workers[i] = new Worker(start, end);
                workers[i].start();
            }

            for (Worker worker : workers) {
                worker.join();
            }
        }

        double vBv = 0.0;
        double vv = 0.0;

        for (int i = 0; i < n; i++) {
            vBv += u[i] * v[i];
            vv += v[i] * v[i];
        }

        System.out.printf(Locale.US, "%.9f%n", Math.sqrt(vBv / vv));
    }
}
